/* One near-full-screen presentation reuses Profile's exact view and persistence logic. */
(()=>{'use strict';const phone=document.querySelector('.fl-home-phone'),trigger=document.getElementById('home-profile-link'),scroll=document.getElementById('home-scroll');if(!phone)return;
const modal=document.createElement('dialog');modal.className='account-modal';modal.id='account-sheet';modal.setAttribute('aria-label','Account');modal.innerHTML='<div class="account-backdrop"></div><section class="account-panel"><header class="account-sheet-header"><span class="account-grabber" aria-hidden="true"></span><h2>Account</h2><button class="account-close" type="button" aria-label="Close Account">×</button></header><div class="account-content"></div></section>';phone.append(modal);
trigger.setAttribute('aria-haspopup','dialog');trigger.setAttribute('aria-controls','account-sheet');trigger.setAttribute('aria-expanded','false');
const panel=modal.querySelector('.account-panel'),backdrop=modal.querySelector('.account-backdrop'),header=modal.querySelector('.account-sheet-header'),host=modal.querySelector('.account-content'),shadow=host.attachShadow({mode:'open'}),reduce=matchMedia('(prefers-reduced-motion: reduce)');
shadow.innerHTML='<link rel="stylesheet" href="profile.css?v=2"><link rel="stylesheet" href="mascot-face.css"><link rel="stylesheet" href="list-polish.css?v=1"><link rel="stylesheet" href="account-profile-embed.css?v=1">'+FitLensProfileView;
const ui=FitLensProfileUI.mount(shadow,{embedded:true,onChange:()=>dispatchEvent(new Event('storage')),onReset:()=>location.reload()});
let motion=null,shade=null,closing=false,opening=false,savedScroll=0,drag=null,dragFrame=0,historyOwned=false,restoreHistory=false,approvedClose=false;
const easing={open:'cubic-bezier(.2,.8,.2,1)',close:'cubic-bezier(.4,0,.8,.4)',snap:'cubic-bezier(.2,.8,.2,1)'};
function place(){const r=phone.getBoundingClientRect();Object.assign(modal.style,{position:'fixed',inset:'auto',left:r.left+'px',top:r.top+'px',width:r.width+'px',height:r.height+'px'});modal.style.setProperty('--account-top',(phone.querySelector('.fl-status').offsetHeight+12)+'px');}
function stop(){motion?.cancel();shade?.cancel();motion=shade=null;}
function animate(from,to,duration,type='open'){
 stop();if(reduce.matches){panel.style.transform='translateY(0)';panel.style.opacity=type==='close'?'1':'0';motion=panel.animate([{opacity:type==='close'?1:0},{opacity:type==='close'?0:1}],{duration:80,fill:'forwards'});}
 else if(type==='open'){motion=panel.animate([{transform:'translateY(100%)'},{transform:'translateY(0)'}],{duration:400,easing:'cubic-bezier(.22,.78,.18,1)',fill:'forwards'});}
 else motion=panel.animate([{transform:`translateY(${from}px)`},{transform:to===1?'translateY(100%)':'translateY(0)'}],{duration,easing:easing[type],fill:'forwards'});
 const start=Number(getComputedStyle(backdrop).opacity);shade=backdrop.animate([{opacity:start},{opacity:type==='close'?0:1}],{duration:reduce.matches?80:type==='open'?220:duration,easing:easing.open,fill:'forwards'});return motion.finished.catch(()=>{});
}
function finishClose(){stop();modal.close();panel.style.transform='translateY(100%)';panel.style.opacity='1';backdrop.style.opacity='0';ui.resetEditor();scroll.style.overflow='';scroll.scrollTop=savedScroll;closing=opening=false;trigger.setAttribute('aria-expanded','false');trigger.focus({preventScroll:true});}
async function dismiss(){if(!modal.open||closing)return;closing=true;opening=false;const y=new DOMMatrix(getComputedStyle(panel).transform).m42;await animate(y,1,drag?.velocity>850?250:290,'close');finishClose();}
function canLeave(){return ui.canLeave();}
function requestClose(){if(closing||!canLeave())return;if(historyOwned){approvedClose=true;history.back();}else{const url=new URL(location.href);url.hash='';history.replaceState(null,'',url);dismiss();}}
async function open({push=true}={}){if(modal.open||closing)return;ui.refresh();approvedClose=false;place();savedScroll=scroll.scrollTop;scroll.style.overflow='hidden';try{sessionStorage.setItem('fitlens:profile-return-scroll:home',String(savedScroll));}catch{}modal.showModal();trigger.setAttribute('aria-expanded','true');opening=true;panel.style.opacity='1';if(push){history.pushState({...history.state,fitlensAccount:true},'',location.pathname+location.search+'#account');historyOwned=true;}else historyOwned=history.state?.fitlensAccount===true;modal.querySelector('.account-close').focus({preventScroll:true});await animate(0,0,400,'open');if(modal.open&&!closing){panel.style.transform='translateY(0)';panel.style.opacity='1';backdrop.style.opacity='1';stop();opening=false;}}
modal.querySelector('.account-close').onclick=requestClose;backdrop.onclick=requestClose;
function escape(){if(ui.hasEditor()){ui.closeEditor();return;}requestClose();}
modal.addEventListener('cancel',e=>{e.preventDefault();escape();});modal.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();escape();}});
addEventListener('popstate',()=>{if(restoreHistory){restoreHistory=false;return;}if(modal.open&&location.hash!=='#account'){if(!approvedClose&&!canLeave()){restoreHistory=true;history.forward();return;}approvedClose=false;dismiss();}else if(!modal.open&&location.hash==='#account')open({push:false});});
function drawDrag(){dragFrame=0;if(!drag)return;panel.style.transform=`translateY(${drag.y}px)`;backdrop.style.opacity=String(Math.max(0,1-Math.max(0,drag.y)/drag.height));}
header.addEventListener('pointerdown',e=>{if(e.target.closest('button')||e.button!==0||closing||opening)return;const t=performance.now(),origin=new DOMMatrix(getComputedStyle(panel).transform).m42,opacity=getComputedStyle(backdrop).opacity;stop();panel.style.transform=`translateY(${origin}px)`;backdrop.style.opacity=opacity;drag={id:e.pointerId,start:e.clientY,origin,y:origin,height:panel.getBoundingClientRect().height,samples:[{y:e.clientY,t}],velocity:0};header.setPointerCapture(e.pointerId);panel.style.willChange='transform';});
header.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;const distance=drag.origin+e.clientY-drag.start;drag.y=distance>=0?distance:Math.max(-12,distance/6);const t=performance.now();drag.samples=drag.samples.filter(s=>t-s.t<100);drag.samples.push({y:e.clientY,t});if(!dragFrame)dragFrame=requestAnimationFrame(drawDrag);},{passive:true});
async function settle(e,canceled=false){if(!drag||drag.id!==e.pointerId)return;cancelAnimationFrame(dragFrame);drawDrag();const gesture=drag,last=gesture.samples.at(-1),first=gesture.samples[0],recent=performance.now()-last.t<100;gesture.velocity=recent&&last.t>first.t?(last.y-first.y)/(last.t-first.t)*1000:0;const from=gesture.y,wants=!canceled&&(from>gesture.height*.25||from>16&&gesture.velocity>850);drag=null;if(wants&&canLeave()){if(historyOwned){approvedClose=true;history.back();}else dismiss();}else{const settling=animate(from,0,260,'snap'),current=motion;await settling;if(motion===current&&!drag&&!closing){panel.style.transform='translateY(0)';backdrop.style.opacity='1';stop();}}if(!drag)panel.style.willChange='';}
header.addEventListener('pointerup',e=>settle(e));header.addEventListener('pointercancel',e=>settle(e,true));header.addEventListener('lostpointercapture',e=>settle(e,true));
addEventListener('resize',()=>{if(modal.open){place();if(drag){drag=null;cancelAnimationFrame(dragFrame);panel.style.transform='translateY(0)';backdrop.style.opacity='1';}}});
reduce.addEventListener('change',()=>{if(!modal.open)return;if(closing)finishClose();else{stop();panel.style.opacity='1';panel.style.transform='translateY(0)';backdrop.style.opacity='1';opening=false;}});
window.FitLensAccountSheet={open,close:requestClose};
if(location.hash==='#account'){requestAnimationFrame(()=>requestAnimationFrame(()=>open({push:false})));}
})();
